function icon(string $name, string $klasse = ''): string
{
    if (!isset(ICONS[$name])) {
        return '';
    }
    $k = trim('icon ' . $klasse);
    return '<svg class="' . $k . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' . ICONS[$name] . '</svg>';
}
